#!/bin/sh
# ⛓️ The closing runs one grant after the other, so that only ONE request of this chain is in the capacity queue at any time: chain.sh
# Waits for the run of the two reference assets (f-pair.log) to end, then asks for each group of final.sh steps in turn with the reservation of its largest measured step.
# Do not edit this file while it runs.
set -u
R=/Users/ueli/Documents/semio
S="$R/🎓️teaching/🏛️architecture/🧍️staffage"
T="$S/🧪️tests/🔭️multiview-coverage"
U="$R/.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️11/☀️22/GET-STAFFAGE-RUNNING-END-TO-END-AND-FINISH-ALL-STAFFAGE-TICKETS"
M="$U/🧰️matrix/MM"
G="$U/🗑️generated/matrix/MM"
BUN=$(ls ~/Library/Caches/semio/runtimes/bun/*/bun | head -1)
cd "$R" || exit 1
until grep -q "^guarded:" "$G/f-pair.log" 2>/dev/null; do sleep 5; done
CMD="'$BUN' '$T/🖨️proofs.ts' --out '$G/f-proofs' --assets finned-heat-exchanger --scales 100" sh "$M/final.sh" 1000 cmd:proofs check:finned-heat-exchanger
CMD="'$BUN' node_modules/typescript/bin/tsc --noEmit -p '$S/📦️packages/🟦️typescript/tsconfig.json'" sh "$M/final.sh" 1500 cmd:tsc
LIMIT_S=5400 sh "$M/final.sh" 2500 resume matrix:weeping-willow check:european-beech heads
sh "$M/final.sh" 3200 suite
CMD="'$BUN' '$M/estimate.ts' --out '$G/f-estimate.jsonl'" LIMIT_S=7200 sh "$M/final.sh" 1800 cmd:estimate
echo "chain ended"
